// -----------------------------------------------------------------------------
// File    : tw_rom_s.v
// Module  : tw_rom_s
// Project : InstRec-FPGA (PG2L100H-6IFBG676, PDS 2022.2-SP6.4)
// Purpose : Per-stage FFT twiddle ROM for fft2048_sdf (T-M1-02).
//
//           One instance per SDF stage k = 1..10 (golden stage s = k+1).
//           The memory holds 2^k words of 32 bit: word j is the golden
//           twiddle tw[j * (2048 >> s)] packed as {im_q15[15:0],
//           re_q15[15:0]} (im in the high half). Files are generated by
//           scripts/export_twiddle_hex.py from golden_pipeline.
//           make_twiddle_q15 - the single bit-level source of truth - so
//           the ROM content is bit-identical to the golden FFT by
//           construction (no runtime arithmetic on the table).
//
//           Stage k = 0 (golden stage 1) has no ROM: its only twiddle is
//           W^0 = 1 and the stage-0 butterfly is a pure add/subtract.
//
// Read timing: synchronous, address-to-q latency of exactly ONE clk
//           cycle for BOTH possible inference styles (BRAM synchronous
//           read / LUTRAM plus output register), so the consumer sees a
//           uniform pipeline regardless of the mapper's choice. Small
//           stages (2^k <= 256) are expected to map into distributed
//           RAM, large ones (2^9, 2^10) into DRM blocks.
//
// File path note: TW_FILE is relative to the synthesis working directory
//           (the PDS project root, e.g. "src/mel/twiddle_s11.hex").
//           The build script must run from instrec_fpga/ - recorded as
//           an integration note for T-M1-06.
// -----------------------------------------------------------------------------

`timescale 1ns / 1ps

module tw_rom_s #(
    // Address width: 2^AW words (AW = k, the SDF stage index, 1..10).
    parameter integer AW = 10,
    // Hex file path (relative to synthesis cwd), $readmemh format:
    // one 32-bit word per line, no address column.
    parameter TW_FILE = "src/mel/twiddle_s11.hex"
) (
    input  wire        clk,
    input  wire [AW-1:0] addr,
    output reg  [31:0] q
);

    // 2^AW x 32 bit twiddle table, {im[15:0], re[15:0]} per word.
    reg [31:0] rom [0:(1 << AW) - 1];

    initial begin
        $readmemh(TW_FILE, rom);
    end

    // Synchronous read: one-cycle latency, uniform for BRAM / LUTRAM.
    always @(posedge clk) begin
        q <= rom[addr];
    end

endmodule